17	// RegisterRecipe 登记一个配方版本。
18	// 配方由配方编号与版本号共同识别；每个版本包含名称和至少一种物料，
19	// 物料记录编号和生产一份所需的克数（正数、最多三位小数）。
20	// 同一版本内物料编号不可重复；已登记的版本内容不可覆盖。
21	// 成功后返回配方视图；reqNo 用于幂等，重复提交相同内容返回同一结果。
22	func (s *Store) RegisterRecipe(reqNo, recipeNo, version, name string, materials []MaterialInput) (*RecipeView, error) {
23		payload := registerRecipePayload{RecipeNo: recipeNo, Version: version, Name: name, Materials: materials}
24		var out RecipeView
25		err := s.write(reqNo, opRegisterRecipe, payload, func(st *persistedState) (json.RawMessage, error) {
26			if recipeNo == "" {
27				return nil, fmt.Errorf("%w: 配方编号不能为空", ErrInvalidInput)
28			}
29			if version == "" {
30				return nil, fmt.Errorf("%w: 版本号不能为空", ErrInvalidInput)
31			}
32			if name == "" {
33				return nil, fmt.Errorf("%w: 配方名称不能为空", ErrInvalidInput)
34			}
35			if len(materials) == 0 {
36				return nil, fmt.Errorf("%w: 配方版本至少包含一种物料", ErrInvalidInput)
37			}
38			if findRecipe(st, recipeNo, version) != nil {
39				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 已存在", ErrRecipeExists, recipeNo, version)
40			}
41	
42			rec := &recipeRecord{RecipeNo: recipeNo, Version: version, Name: name}
43			seen := make(map[string]bool, len(materials))
44			for _, m := range materials {
45				if m.MaterialNo == "" {
46					return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
47				}
48				if seen[m.MaterialNo] {
49					return nil, fmt.Errorf("%w: 配方版本内物料编号 %q 重复", ErrInvalidInput, m.MaterialNo)
50				}
51				seen[m.MaterialNo] = true
52				milli, err := parseGrams(m.Grams)
53				if err != nil {
54					return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, m.MaterialNo, err)
55				}
56				rec.Materials = append(rec.Materials, materialRecord{MaterialNo: m.MaterialNo, GramsMilli: milli})
57			}
58	
59			view := buildRecipeView(rec)
60			raw, err := json.Marshal(view)
61			if err != nil {
62				return nil, err
63			}
64			st.Recipes = append(st.Recipes, rec)
65			return raw, nil
66		}, &out)
67		if err != nil {
68			return nil, err
69		}
70		return &out, nil
71	}
