1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件无法读取、解析，任一批次绑定的配方版本未登记，
31	// 已保存投料的物料编号不属于该批次绑定的配方版本，
32	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
33	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
34	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
35	func Open(dir string) (*Store, error) {
36		if dir == "" {
37			return nil, errors.New("数据位置不能为空")
38		}
39		if err := os.MkdirAll(dir, 0o755); err != nil {
40			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
41		}
42		info, err := os.Stat(dir)
43		if err != nil {
44			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
45		}
46		if !info.IsDir() {
47			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
48		}
49	
50		lockPath := filepath.Join(dir, lockFileName)
51		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
52		if err != nil {
53			return nil, fmt.Errorf("打开锁文件失败: %w", err)
54		}
55	
56		s := &Store{dir: dir, lockFile: lf}
57		if err := s.load(); err != nil {
58			lf.Close()
59			return nil, err
60		}
61		return s, nil
62	}
63	
64	// Close 释放台账占用的文件锁。
65	func (s *Store) Close() error {
66		s.mu.Lock()
67		defer s.mu.Unlock()
68		if s.lockFile == nil {
69			return nil
70		}
71		err := s.lockFile.Close()
72		s.lockFile = nil
73		return err
74	}
75	
76	func (s *Store) lockExclusive() error {
77		if s.lockFile == nil {
78			return errors.New("台账已关闭")
79		}
80		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
81			return fmt.Errorf("锁定台账失败: %w", err)
82		}
83		return nil
84	}
85	
86	func (s *Store) lockShared() error {
87		if s.lockFile == nil {
88			return errors.New("台账已关闭")
89		}
90		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
91			return fmt.Errorf("锁定台账失败: %w", err)
92		}
93		return nil
94	}
95	
96	func (s *Store) unlock() {
97		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
98	}
99	
100	func (s *Store) load() error {
101		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
102		if err != nil {
103			if os.IsNotExist(err) {
104				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
105				return nil
106			}
107			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
108		}
109		if len(data) == 0 {
110			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
111			return nil
112		}
113		var st persistedState
114		if err := json.Unmarshal(data, &st); err != nil {
115			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
116		}
117		if st.Version != stateVersion {
118			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
119		}
120		if err := validateState(&st); err != nil {
121			return err
122		}
123		if st.Requests == nil {
124			st.Requests = map[string]*requestRecord{}
125		}
126		s.state = &st
127		return nil
128	}
129	
130	// validateState 检查台账的引用完整性与投料数量合法性：
131	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
132	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
133	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
134	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
135	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
136	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
137	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
138	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
139	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
140	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
141	func validateState(st *persistedState) error {
142		for _, b := range st.Batches {
143			if b == nil {
144				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
145			}
146			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
147			if r == nil {
148				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
149					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
150			}
151			if err := validateFeedings(b, r); err != nil {
152				return err
153			}
154		}
155		return nil
156	}
157	
158	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
159	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
160	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
161	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
162	// 在此拒绝。
163	func validateFeedings(b *batchRecord, r *recipeRecord) error {
164		sums := map[string]gramsMilli{}
165		for _, f := range b.Feedings {
166			belongs := false
167			for _, m := range r.Materials {
168				if m.MaterialNo == f.MaterialNo {
169					belongs = true
170					break
171				}
172			}
173			if !belongs {
174				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
175					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
176			}
177			if f.GramsMilli <= 0 {
178				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
179					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
180			}
181			sum := sums[f.MaterialNo]
182			if f.GramsMilli > maxGramsMilli-sum {
183				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
184					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
185			}
186			sums[f.MaterialNo] = sum + f.GramsMilli
187		}
188		return nil
189	}
190	
191	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
192	func (s *Store) persist(st *persistedState) error {
193		data, err := json.MarshalIndent(st, "", "  ")
194		if err != nil {
195			return err
196		}
197		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
198		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
199		if err != nil {
200			return err
201		}
202		if _, err := f.Write(data); err != nil {
203			f.Close()
204			return err
205		}
206		if err := f.Sync(); err != nil {
207			f.Close()
208			return err
209		}
210		if err := f.Close(); err != nil {
211			return err
212		}
213		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
214			return err
215		}
216		if d, err := os.Open(s.dir); err == nil {
217			_ = d.Sync()
218			_ = d.Close()
219		}
220		return nil
221	}
222	
223	func cloneState(st *persistedState) (*persistedState, error) {
224		data, err := json.Marshal(st)
225		if err != nil {
226			return nil, err
227		}
228		var out persistedState
229		if err := json.Unmarshal(data, &out); err != nil {
230			return nil, err
231		}
232		if out.Requests == nil {
233			out.Requests = map[string]*requestRecord{}
234		}
235		return &out, nil
236	}
237	
238	// write 是所有写入操作的统一入口：
239	//   - reqNo 为空直接报错；
240	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
241	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
242	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
243	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
244	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
245		if reqNo == "" {
246			return errors.New("请求编号不能为空")
247		}
248		s.mu.Lock()
249		defer s.mu.Unlock()
250		if err := s.lockExclusive(); err != nil {
251			return err
252		}
253		defer s.unlock()
254	
255		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
256		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
257		if err := s.load(); err != nil {
258			return err
259		}
260	
261		payloadRaw, err := json.Marshal(payload)
262		if err != nil {
263			return err
264		}
265		payloadStr := string(payloadRaw)
266	
267		if req, ok := s.state.Requests[reqNo]; ok {
268			if req.Op != op || req.Payload != payloadStr {
269				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
270					ErrRequestConflict, reqNo, req.Op, op)
271			}
272			if err := json.Unmarshal(req.Result, out); err != nil {
273				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
274			}
275			return nil
276		}
277	
278		clone, err := cloneState(s.state)
279		if err != nil {
280			return err
281		}
282		result, err := apply(clone)
283		if err != nil {
284			return err
285		}
286		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
287		if err := s.persist(clone); err != nil {
288			return fmt.Errorf("保存台账失败: %w", err)
289		}
290		s.state = clone
291		if err := json.Unmarshal(result, out); err != nil {
292			return fmt.Errorf("解析请求结果失败: %w", err)
293		}
294		return nil
295	}
296	
297	// read 在共享锁下读取当前状态。
298	func (s *Store) read(fn func(*persistedState) error) error {
299		s.mu.Lock()
300		defer s.mu.Unlock()
301		if err := s.lockShared(); err != nil {
302			return err
303		}
304		defer s.unlock()
305		if err := s.load(); err != nil {
306			return err
307		}
308		return fn(s.state)
309	}
310	
311	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
312	
313	func buildRecipeView(r *recipeRecord) *RecipeView {
314		mats := make([]MaterialView, 0, len(r.Materials))
315		for _, m := range r.Materials {
316			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
317		}
318		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
319	}
320	
321	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
322		v := &BatchView{
323			BatchNo:         b.BatchNo,
324			RecipeNo:        r.RecipeNo,
325			RecipeVersion:   r.Version,
326			RecipeName:      r.Name,
327			PlannedPortions: b.PlannedPortions,
328			Status:          b.Status,
329			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
330			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
331		}
332	
333		for _, f := range b.Feedings {
334			v.Feedings = append(v.Feedings, FeedingView{
335				Seq:        f.Seq,
336				MaterialNo: f.MaterialNo,
337				Grams:      f.GramsMilli.String(),
338				Time:       f.Time,
339				Registrar:  f.Registrar,
340			})
341		}
342	
343		for _, m := range r.Materials {
344			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
345			if err != nil {
346				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
347			}
