8		"strconv"
9		"strings"
10	)
11	
12	// gramsMilli 以千分之一克为单位定点存储克数，避免浮点误差。
13	type gramsMilli int64
14	
15	// maxGramsMilli 是同一批次内每种物料累计实投的上限，
16	// 即 9223372036854775.807 克（math.MaxInt64 个千分之一克）。
17	const maxGramsMilli gramsMilli = math.MaxInt64
18	
19	var gramsPattern = regexp.MustCompile(`^(\d+)(?:\.(\d{1,3}))?$`)
20	
21	// parseGrams 将克数字符串精确解析为千分之一克。
22	// 规则：必须为正数，且最多三位小数（如 100、100.5、0.001 合法；0、-1、1.2345 非法）。
23	func parseGrams(s string) (gramsMilli, error) {
24		s = strings.TrimSpace(s)
25		if s == "" {
26			return 0, errors.New("克数不能为空")
27		}
28		m := gramsPattern.FindStringSubmatch(s)
29		if m == nil {
30			return 0, fmt.Errorf("克数 %q 不合法：必须为正数且最多三位小数", s)
31		}
32		whole, err := strconv.ParseInt(m[1], 10, 64)
33		if err != nil {
34			return 0, fmt.Errorf("克数 %q 不合法", s)
35		}
36		var frac int64
37		if m[2] != "" {
38			f := m[2]
39			for len(f) < 3 {
40				f += "0"
41			}
42			frac, err = strconv.ParseInt(f, 10, 64)
43			if err != nil {
44				return 0, fmt.Errorf("克数 %q 不合法", s)
45			}
46		}
47		// 先做溢出检查，避免整数回绕把超大克数变成较小的值。
48		if whole > int64(maxGramsMilli)/1000 ||
49			(whole == int64(maxGramsMilli)/1000 && frac > int64(maxGramsMilli)%1000) {
50			return 0, fmt.Errorf("克数 %q 超出范围：单次数量不能超过 %s 克", s, maxGramsMilli)
51		}
52		milli := whole*1000 + frac
53		if milli <= 0 {
54			return 0, fmt.Errorf("克数 %q 必须为正数", s)
55		}
56		return gramsMilli(milli), nil
57	}
58	
59	// String 将千分之一克格式化为克数字符串，去掉末尾多余的 0。
60	func (g gramsMilli) String() string {
61		sign := ""
62		v := int64(g)
63		if v < 0 {
64			sign = "-"
65			v = -v
66		}
67		w, f := v/1000, v%1000
68		if f == 0 {
69			return sign + strconv.FormatInt(w, 10)
70		}
71		fs := strings.TrimRight(fmt.Sprintf("%03d", f), "0")
72		return sign + strconv.FormatInt(w, 10) + "." + fs
73	}
74	
75	// multiplyPortions 将克数与份数相乘，检查溢出。
76	func multiplyPortions(g gramsMilli, portions int) (gramsMilli, error) {
77		if portions <= 0 {
78			return 0, errors.New("份数必须为正整数")
79		}
80		v := int64(g)
81		if v > (1<<63-1)/int64(portions) {
82			return 0, fmt.Errorf("数量过大：%s 克 × %d 份溢出", g, portions)
83		}
84		return gramsMilli(v * int64(portions)), nil
