210			t.Fatal(err)
211		}
212		if _, err := s.CreateBatch("b3", "B3", "R1", "v1", 10); err != nil {
213			t.Fatal(err)
214		}
215		if _, err := s.StartBatch("s3", "B3"); err != nil {
216			t.Fatal(err)
217		}
