package release

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Open 时任一配方版本的任一物料每份克数为零或负数，都必须返回
// ErrCorruptData：不论该版本是否被批次使用；错误信息需包含配方编号、
// 版本号与物料编号；不返回可用的台账对象，也不改写原文件。
func TestOpenRejectsNonPositiveRecipeGrams(t *testing.T) {
	cases := []struct {
		name    string
