		t.Fatalf("无投料时累计实投为零、差额为负均属正常，得到 %+v", m)
	}

	// 重新打开（触发完整校验）后数据仍可用。
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if err != nil {
		t.Fatalf("含 0.001 克用量的台账应能正常打开: %v", err)
	}
	defer s2.Close()
	if _, err := s2.GetRecipe("R1", "v1"); err != nil {
		t.Fatalf("重新打开后配方查询应成功: %v", err)
	}
}

