		t.Fatalf("含 0.001 克用量的台账应能正常打开: %v", err)
	}
	defer s2.Close()
	if _, err := s2.GetRecipe("R1", "v1"); err != nil {
		t.Fatalf("重新打开后配方查询应成功: %v", err)
	}
}
